const item = {
  ...$('Normalize Shipment Data').item.json,
  ...($input.item.json.output || {})
};

// AI shipment classification
const shipmentStatus = item.shipment_status || item.shipmentStatus || "UNKNOWN";
const exceptionType = item.exception_type || "NONE";
const priority = item.priority || "LOW";
const confidence = Number(item.confidence ?? 0);
const requiresHumanReview = Boolean(item.requires_human_review);
const reason = item.reason || "No additional reason provided.";

// Shipment information
const shipmentId = item.shipmentId || "UNKNOWN";
const trackingNumber = item.trackingNumber || "N/A";
const customerName = item.customerName || "Customer";
const customerPhone = item.customerPhone || "";
const origin = item.origin || "N/A";
const destination = item.destination || "N/A";
const currentLocation = item.currentLocation || "N/A";
const expectedDelivery = item.expectedDelivery || "N/A";
const lastUpdated = item.lastUpdated || "N/A";
const remarks = item.remarks || "";

// Build notification message
let messageText;

if (exceptionType !== "NONE") {
  messageText = [
    "Shipment Exception Alert",
    "",
    `Shipment: ${shipmentId}`,
    `Tracking: ${trackingNumber}`,
    `Status: ${shipmentStatus}`,
    `Exception: ${exceptionType}`,
    `Priority: ${priority}`,
    `Current Location: ${currentLocation}`,
    `Expected Delivery: ${expectedDelivery}`,
    "",
    `Reason: ${reason}`,
    "",
    requiresHumanReview
      ? "Action: Human review required."
      : "Action: Continue operational monitoring."
  ].join("\n");
} else {
  messageText = [
    "Shipment Status Update",
    "",
    `Hi ${customerName},`,
    "",
    `Your shipment ${shipmentId} is currently ${shipmentStatus}.`,
    `Tracking: ${trackingNumber}`,
    `From: ${origin}`,
    `To: ${destination}`,
    `Current location: ${currentLocation}`,
    `Expected delivery: ${expectedDelivery}`,
    "",
    "No shipment exception was detected."
  ].join("\n");
}

// Sanitize phone number
const rawPhone = String(customerPhone || "");

const recipientPhone = rawPhone
  .replace(/\D/g, "")
  .replace(/^0+/, "");

// Final output
return {
  json: {
    ...item,

    shipmentStatus,
    exceptionType,
    priority,
    confidence,
    requiresHumanReview,
    reason,

    notificationType:
      exceptionType === "NONE"
        ? "STATUS_UPDATE"
        : "EXCEPTION_ALERT",

    notificationPriority: priority,

    messageText,
    recipientPhone,

    notificationPreparedAt: new Date().toISOString()
  }
};

